using System.Security.Claims;
using System.Text;
using Core.Authorization;
using Core.Modules;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;
using Modules.Expenses.DTOs;
using Modules.Expenses.Repositories;
using Modules.Expenses.Services;
using Shared.Primitives.Identifiers;

namespace Modules.Expenses;

public static class ExpensesModuleExtensions
{
    public static IServiceCollection AddExpensesModule(this IServiceCollection services) { services.AddSingleton<IModuleManifestProvider, ExpensesModuleManifestProvider>(); services.AddSingleton<ExpenseRepository>(); services.AddSingleton<ExpenseService>(); return services; }
    public static WebApplication MapExpensesModule(this WebApplication app)
    {
        var g = app.MapGroup("/api/v1/expenses").WithTags("Expenses").RequireAuthorization().RequireRateLimiting("api")
            .AddEndpointFilter(async (context, next) =>
            {
                var http = context.HttpContext;
                if (!Guid.TryParse(http.User.FindFirstValue("tenant_id"), out var tenantId) ||
                    !Guid.TryParse(http.User.FindFirstValue("membership_id"), out var membershipId))
                    return Results.Unauthorized();
                if (!Guid.TryParse(http.Request.RouteValues["entityId"]?.ToString(), out var entityId))
                    return Results.BadRequest(new { code = "expenses.entity_scope_invalid" });
                if (Guid.TryParse(http.User.FindFirstValue("legal_entity_id"), out var claimEntity) && claimEntity != entityId)
                    return Results.Forbid();
                var tenant = new TenantId(tenantId);
                var subjects = http.RequestServices.GetRequiredService<IAuthorizationSubjectStore>();
                var authorizer = http.RequestServices.GetRequiredService<IPermissionAuthorizer>();
                var subject = await subjects.LoadAsync(tenant, membershipId, http.RequestAborted);
                if (subject is null) return Results.Unauthorized();
                if (!authorizer.Authorize(subject, PermissionFor(http), PermissionScope.ForLegalEntity(tenant, new(entityId))))
                    return Results.Forbid();
                return await next(context);
            });
        g.MapGet("/legal-entities/{entityId:guid}/categories", async (Guid entityId, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.ListCategoriesAsync(Tenant(h), entityId, ct)));
        g.MapPost("/legal-entities/{entityId:guid}/categories", async (Guid entityId, CreateExpenseCategoryRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => r.LegalEntityId != entityId ? Results.BadRequest(new { code = "expenses.entity_scope_invalid" }) : await Execute(h, entityId, () => s.CreateCategoryAsync(Tenant(h), r, ct), 201));
        g.MapPost("/legal-entities/{entityId:guid}/categories/{categoryId:guid}/versions", async (Guid entityId, Guid categoryId, CreateExpenseCategoryVersionRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.CreateCategoryVersionAsync(Tenant(h), entityId, categoryId, r, ct), 201));
        g.MapPost("/legal-entities/{entityId:guid}/category-versions/{versionId:guid}/publish", async (Guid entityId, Guid versionId, PublishExpenseCategoryVersionRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.PublishCategoryVersionAsync(Tenant(h), entityId, versionId, r, ct)));
        g.MapGet("/legal-entities/{entityId:guid}", async (Guid entityId, Guid? employeeId, string? state, string? search, int? page, int? pageSize, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.ListAsync(Tenant(h), entityId, employeeId, state, search, page ?? 1, pageSize ?? 50, ct)));
        g.MapPost("/legal-entities/{entityId:guid}", async (Guid entityId, CreateExpenseRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => r.LegalEntityId != entityId ? Results.BadRequest(new { code = "expenses.entity_scope_invalid" }) : await Execute(h, entityId, () => s.CreateAsync(Tenant(h), r, ct), 201));
        g.MapGet("/legal-entities/{entityId:guid}/{id:guid}", async (Guid entityId, Guid id, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, async () => await s.GetAsync(Tenant(h), entityId, id, ct) ?? throw new ExpenseRepositoryException("expenses.expense_not_found")));
        g.MapPut("/legal-entities/{entityId:guid}/{id:guid}", async (Guid entityId, Guid id, UpdateExpenseRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.UpdateAsync(Tenant(h), entityId, id, r, ct)));
        foreach (var action in new[] { "submit", "finalize", "reverse" }) { var route = $"/legal-entities/{{entityId:guid}}/{{id:guid}}/{action}"; g.MapPost(route, async (Guid entityId, Guid id, ExpenseActionRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.TransitionAsync(Tenant(h), entityId, id, r, action, ct))); }
        g.MapGet("/legal-entities/{entityId:guid}/{id:guid}/evidence", async (Guid entityId, Guid id, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.ListEvidenceAsync(Tenant(h), entityId, id, ct)));
        g.MapPost("/legal-entities/{entityId:guid}/{id:guid}/evidence/upload-intent", async (Guid entityId, Guid id, CreateExpenseEvidenceUploadRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.CreateEvidenceUploadIntentAsync(Tenant(h), Actor(h), Membership(h), entityId, id, r, ct)));
        g.MapPost("/legal-entities/{entityId:guid}/{id:guid}/evidence/complete", async (Guid entityId, Guid id, CompleteExpenseEvidenceUploadRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.CompleteEvidenceUploadAsync(Tenant(h), Actor(h), Membership(h), entityId, id, r, ct)));
        g.MapGet("/legal-entities/{entityId:guid}/{id:guid}/evidence/{evidenceId:guid}/download", async (Guid entityId, Guid id, Guid evidenceId, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.CreateEvidenceDownloadAsync(Tenant(h), entityId, id, evidenceId, ct)));
        g.MapGet("/legal-entities/{entityId:guid}/{id:guid}/history", async (Guid entityId, Guid id, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.ListHistoryAsync(Tenant(h), entityId, id, ct)));
        g.MapPost("/legal-entities/{entityId:guid}/{id:guid}/evidence", async (Guid entityId, Guid id, AddExpenseEvidenceRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.AddEvidenceAsync(Tenant(h), entityId, id, r, ct), 201));
        g.MapGet("/legal-entities/{entityId:guid}/{id:guid}/missing-receipt", async (Guid entityId, Guid id, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.GetMissingReceiptDeclarationAsync(Tenant(h), entityId, id, ct)));
        g.MapPost("/legal-entities/{entityId:guid}/{id:guid}/missing-receipt", async (Guid entityId, Guid id, DeclareMissingReceiptRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.DeclareMissingReceiptAsync(Tenant(h), Actor(h), entityId, id, r, ct), 201));
        g.MapGet("/legal-entities/{entityId:guid}/{id:guid}/itemizations", async (Guid entityId, Guid id, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.ListItemizationsAsync(Tenant(h), entityId, id, ct)));
        g.MapPost("/legal-entities/{entityId:guid}/{id:guid}/itemizations", async (Guid entityId, Guid id, CreateExpenseItemizationRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.AddItemizationAsync(Tenant(h), entityId, id, r, ct), 201));
        g.MapDelete("/legal-entities/{entityId:guid}/{id:guid}/itemizations/{itemizationId:guid}", async (Guid entityId, Guid id, Guid itemizationId, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, async () => { await s.DeleteItemizationAsync(Tenant(h), entityId, id, itemizationId, ct); return new { deleted = true }; }));
        g.MapGet("/legal-entities/{entityId:guid}/{id:guid}/participants", async (Guid entityId, Guid id, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.ListParticipantsAsync(Tenant(h), entityId, id, ct)));
        g.MapPost("/legal-entities/{entityId:guid}/{id:guid}/participants", async (Guid entityId, Guid id, AddExpenseParticipantRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.AddParticipantAsync(Tenant(h), entityId, id, r, ct), 201));
        g.MapPost("/legal-entities/{entityId:guid}/{id:guid}/evaluate-policy", async (Guid entityId, Guid id, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.EvaluatePolicyAsync(Tenant(h), entityId, id, ct)));
        g.MapPost("/legal-entities/{entityId:guid}/{id:guid}/approval/request", async (Guid entityId, Guid id, ExpenseApprovalRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.RequestApprovalAsync(Tenant(h), Actor(h), Membership(h), entityId, id, r.Reason, ct)));
        g.MapPost("/legal-entities/{entityId:guid}/{id:guid}/approval/decision", async (Guid entityId, Guid id, ExpenseApprovalDecisionRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.DecideApprovalAsync(Tenant(h), Actor(h), Membership(h), entityId, id, r, ct)));
        g.MapPost("/legal-entities/{entityId:guid}/policies", async (Guid entityId, CreateExpensePolicyRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => r.LegalEntityId != entityId ? Results.BadRequest(new { code = "expenses.entity_scope_invalid" }) : await Execute(h, entityId, () => s.CreatePolicyAsync(Tenant(h), r, ct), 201));
        g.MapPost("/legal-entities/{entityId:guid}/policies/{policyId:guid}/versions", async (Guid entityId, Guid policyId, CreateExpensePolicyVersionRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.CreatePolicyVersionAsync(Tenant(h), entityId, policyId, r, ct), 201));
        g.MapPost("/legal-entities/{entityId:guid}/policy-versions/{versionId:guid}/publish", async (Guid entityId, Guid versionId, PublishExpensePolicyVersionRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.PublishPolicyVersionAsync(Tenant(h), entityId, versionId, r, ct)));
        g.MapGet("/legal-entities/{entityId:guid}/reports", async (Guid entityId, string? state, string? search, int? page, int? pageSize, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.ListReportsAsync(Tenant(h), entityId, state, search, page ?? 1, pageSize ?? 50, ct)));
        g.MapGet("/legal-entities/{entityId:guid}/reports/export", async (Guid entityId, string? state, string? search, HttpContext h, ExpenseService s, CancellationToken ct) => { if (!Guid.TryParse(h.User.FindFirstValue("tenant_id"), out _)) return Results.Forbid(); try { var csv = await s.ExportReportsCsvAsync(Tenant(h), entityId, state, search, ct); return Results.File(Encoding.UTF8.GetBytes(csv), "text/csv; charset=utf-8", "expense-reports.csv"); } catch (ExpenseRepositoryException ex) { return Results.Problem(statusCode: 400, title: ex.Code, extensions: new Dictionary<string, object?> { ["code"] = ex.Code }); } });
        g.MapGet("/legal-entities/{entityId:guid}/reports/exceptions", async (Guid entityId, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.GetExceptionSummaryAsync(Tenant(h), entityId, ct)));
        g.MapPost("/legal-entities/{entityId:guid}/reports", async (Guid entityId, CreateExpenseReportRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => r.LegalEntityId != entityId ? Results.BadRequest(new { code = "expenses.entity_scope_invalid" }) : await Execute(h, entityId, () => s.CreateReportAsync(Tenant(h), r, ct), 201));
        g.MapGet("/legal-entities/{entityId:guid}/advances", async (Guid entityId, string? state, Guid? employeeId, bool? overdue, int? page, int? pageSize, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.ListAdvancesAsync(Tenant(h), entityId, state, employeeId, overdue == true, page ?? 1, pageSize ?? 50, ct)));
        g.MapPost("/legal-entities/{entityId:guid}/advances", async (Guid entityId, CreateBusinessAdvanceRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => r.LegalEntityId != entityId ? Results.BadRequest(new { code = "expenses.entity_scope_invalid" }) : await Execute(h, entityId, () => s.CreateAdvanceAsync(Tenant(h), r, ct), 201));
        g.MapPost("/legal-entities/{entityId:guid}/advances/{id:guid}/approve", async (Guid entityId, Guid id, ExpenseActionRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.TransitionAdvanceAsync(Tenant(h), entityId, id, r.Version, "approve", ct)));
        g.MapPost("/legal-entities/{entityId:guid}/advances/{id:guid}/issue", async (Guid entityId, Guid id, IssueBusinessAdvanceRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.IssueAdvanceAsync(Tenant(h), entityId, id, Actor(h), Membership(h), r, ct)));
        g.MapPost("/legal-entities/{entityId:guid}/advances/{id:guid}/settle", async (Guid entityId, Guid id, ExpenseActionRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.TransitionAdvanceAsync(Tenant(h), entityId, id, r.Version, "settle", ct)));
        g.MapPost("/legal-entities/{entityId:guid}/advances/{id:guid}/apply", async (Guid entityId, Guid id, ApplyBusinessAdvanceRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.ApplyAdvanceAsync(Tenant(h), entityId, id, r, ct)));
        g.MapPost("/legal-entities/{entityId:guid}/advances/{id:guid}/return-payment", async (Guid entityId, Guid id, ReturnBusinessAdvanceRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.ReturnAdvanceAsync(Tenant(h), entityId, id, r, ct)));
        g.MapGet("/legal-entities/{entityId:guid}/corporate-card/inbox", async (Guid entityId, string? state, string? search, int? page, int? pageSize, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.ListCardTransactionsAsync(Tenant(h), entityId, state, search, page ?? 1, pageSize ?? 50, ct)));
        g.MapPost("/legal-entities/{entityId:guid}/corporate-card/transactions/import", async (Guid entityId, ImportExpenseCardTransactionRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.ImportCardTransactionAsync(Tenant(h), entityId, r, ct), 201));
        g.MapPost("/legal-entities/{entityId:guid}/corporate-card/transactions/{cardId:guid}/clear", async (Guid entityId, Guid cardId, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.ClearCardTransactionAsync(Tenant(h), entityId, cardId, ct)));
        g.MapPost("/legal-entities/{entityId:guid}/corporate-card/transactions/{cardId:guid}/adjustments", async (Guid entityId, Guid cardId, RecordExpenseCardAdjustmentRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.RecordCardAdjustmentAsync(Tenant(h), entityId, cardId, r, ct), 201));
        g.MapPost("/legal-entities/{entityId:guid}/corporate-card/transactions/{cardId:guid}/match", async (Guid entityId, Guid cardId, MatchExpenseCardTransactionRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.MatchCardTransactionAsync(Tenant(h), entityId, cardId, r, ct)));
        g.MapPost("/legal-entities/{entityId:guid}/corporate-card/transactions/{cardId:guid}/allocate", async (Guid entityId, Guid cardId, AllocateExpenseCardTransactionRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.AllocateCardTransactionAsync(Tenant(h), entityId, cardId, r, ct)));
        g.MapPost("/legal-entities/{entityId:guid}/corporate-card/transactions/{cardId:guid}/personal", async (Guid entityId, Guid cardId, MarkExpenseCardPersonalRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.MarkCardTransactionPersonalAsync(Tenant(h), entityId, cardId, r, ct)));
        g.MapGet("/legal-entities/{entityId:guid}/employee-repayments", async (Guid entityId, Guid? employeeId, string? state, int? page, int? pageSize, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.ListEmployeeRepaymentsAsync(Tenant(h), entityId, employeeId, state, page ?? 1, pageSize ?? 50, ct)));
        g.MapPost("/legal-entities/{entityId:guid}/employee-repayments/{repaymentId:guid}/settle", async (Guid entityId, Guid repaymentId, SettleEmployeeRepaymentRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.SettleEmployeeRepaymentAsync(Tenant(h), entityId, repaymentId, Actor(h), Membership(h), r, ct)));
        g.MapPut("/legal-entities/{entityId:guid}/{id:guid}/mileage", async (Guid entityId, Guid id, SetMileageDetailRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.SetMileageDetailAsync(Tenant(h), entityId, id, r, ct)));
        g.MapPut("/legal-entities/{entityId:guid}/{id:guid}/per-diem", async (Guid entityId, Guid id, SetPerDiemDetailRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.SetPerDiemDetailAsync(Tenant(h), entityId, id, r, ct)));
        g.MapPost("/legal-entities/{entityId:guid}/rate-policies", async (Guid entityId, CreateExpenseRatePolicyRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => r.LegalEntityId != entityId ? Results.BadRequest(new { code = "expenses.entity_scope_invalid" }) : await Execute(h, entityId, () => s.CreateRatePolicyAsync(Tenant(h), r, ct), 201));
        g.MapPost("/legal-entities/{entityId:guid}/rate-policies/{id:guid}/publish", async (Guid entityId, Guid id, PublishExpenseRatePolicyRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.PublishRatePolicyAsync(Tenant(h), entityId, id, r, ct)));
        g.MapGet("/legal-entities/{entityId:guid}/{id:guid}/dimensions", async (Guid entityId, Guid id, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.ListDimensionsAsync(Tenant(h), entityId, id, ct)));
        g.MapPut("/legal-entities/{entityId:guid}/{id:guid}/dimensions", async (Guid entityId, Guid id, SetExpenseDimensionRequest r, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.SetDimensionAsync(Tenant(h), entityId, id, r, ct)));
        g.MapPost("/legal-entities/{entityId:guid}/reimbursements/prepare", async (Guid entityId, string? currency, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.PrepareReimbursementBatchAsync(Tenant(h), entityId, currency ?? "EGP", ct), 201));
        g.MapPost("/legal-entities/{entityId:guid}/reimbursements/{batchId:guid}/pay", async (Guid entityId, Guid batchId, PayExpenseReimbursementBatchRequest request, HttpContext h, ExpenseService s, CancellationToken ct) => await Execute(h, entityId, () => s.PayReimbursementBatchAsync(Tenant(h), entityId, batchId, Actor(h), Membership(h), request, ct), 201));
